"""Bluetooth Drag Racing development pages. Uses the studio page renderer."""
from pathlib import Path
from bs4 import BeautifulSoup
ROOT=Path(__file__).resolve().parents[1]
def build(page):
 base='/assets/apps/bluetooth-racing/'
 body=f'''<style>.drag-hero{{background:linear-gradient(90deg,#100d27ed,#100d2760),url({base}garage-art.png) center/cover;border:1px solid #8957b2;border-radius:22px;padding:clamp(1.5rem,5vw,4rem);min-height:420px;display:flex;align-items:center}}.drag-hero>div{{max-width:640px}}.drag-hero h1{{font-style:italic;color:#ffd35b}}.drag-grid{{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}}.drag-grid article{{padding:1.4rem;background:#17122a;border:1px solid #5a426e;border-radius:15px}}.drag-shots{{display:grid;grid-template-columns:1fr 1fr;gap:1rem}}.drag-shots img{{width:100%;height:auto;border-radius:12px}}.drag-shots figure{{margin:0}}@media(max-width:700px){{.drag-grid,.drag-shots{{grid-template-columns:1fr}}}}</style>
 <section class="drag-hero"><div><p class="eyebrow">Android · Development preview</p><h1>Bluetooth Drag Racing</h1><p class="lead">Build it. Tune it. Race it.</p><p>A retro-inspired, side-on drag racer built around quick runs, clean shifts and a garage that feels like yours. Rev at the lights, launch on green and carry your speed through the finish.</p><p><a class="button" href="#gameplay">See the game</a> · <a href="/bluetooth-racing/support/">Controls and help</a></p><p>Coming soon. Not yet available on Google Play.</p></div></section>
 <section><h2>Your next tenth of a second</h2><div class="drag-grid"><article><h3>Find your pace</h3><p>Run the quarter mile or half mile. Choose Rookie, Street or Pro computer opponents, or race a translucent replay of your own recorded best run.</p></article><article><h3>Build your garage</h3><p>Five fictional cars span classic muscle, street tuners and sports coupes. Rotate the garage view, choose paint and wheel finishes, and keep a separate build for every car.</p></article><article><h3>Make upgrades count</h3><p>Earn race credits for tires, engines, transmissions, nitrous, turbo and weight reduction. Adjust final-drive gearing and compare simulated acceleration in the dyno shop.</p></article></div></section>
 <section id="gameplay"><h2>Built for the race</h2><p>Actual Android development-build captures. The interface and features may change before release.</p><div class="drag-shots"><figure><img src="{base}race.png" alt="Side-on drag race with compact RPM strip, gear, speed, shift and gas controls" loading="lazy"><figcaption>More track, less dashboard.</figcaption></figure><figure><img src="{base}showroom.png" alt="Five fictional cars in the earned-credit showroom" loading="lazy"><figcaption>Find your next build.</figcaption></figure><figure><img src="{base}garage.png" alt="Rotatable car preview, installed upgrades and paint choices" loading="lazy"><figcaption>Your own parts, paint and tune.</figcaption></figure><figure><img src="{base}dyno.png" alt="Simulated acceleration against RPM and final-drive controls" loading="lazy"><figcaption>Compare gearing before your next run.</figcaption></figure></div></section>
 <section><h2>Race a friend nearby</h2><p>Bluetooth Host and Join are built in for paired Android devices. Both players need the same app version. Physical two-device race and connection acceptance is still being verified; Bluetooth is not yet a verified release feature.</p><h2>Six places to put your build to work</h2><p>Race the Drag Strip, Dirt Road, Downtown, Waterfront, Desert Highway or Night Airfield. Choose dry, damp or rainy conditions. Surface grip, wheelspin, dust and wet-road spray affect the experience. Compare a saved build against your current tuning in the dyno shop.</p><h2>Play on your terms</h2><p>Solo races, garage upgrades, records and ghosts work offline without an account. Choose manual or automatic shifting, left- or right-handed controls, MPH or KPH, and optional engine audio. Production ads and real-money checkout are not active in the current release candidate. Earned-credit unlocks remain available offline. The planned launch is free with optional purchases and ads only between completed races. The planned one-time paint, gold-wheel and Apex GT purchases are US$0.99 each, with earned-credit alternatives. Google Play availability is not yet announced.</p><p>This is an arcade drag racer. The dyno shows the game’s simulated acceleration, not a real-world horsepower measurement. Ghosts are saved by car, race distance and weather/surface conditions; finish a computer run first to create one.</p></section><p><a href="/bluetooth-racing/privacy/">Privacy policy</a> · <a href="/bluetooth-racing/support/">Support</a></p>'''
 page('/bluetooth-racing/','Bluetooth Drag Racing for Android','A retro-inspired Android drag racer with quarter- and half-mile runs, five fictional cars, upgrades, personal-best ghosts and Bluetooth play in testing.',body,'https://tripperdeelabs.com'+base+'race.png')
 page('/bluetooth-racing/privacy/','Bluetooth Drag Racing privacy policy','Local saves, recorded ghost runs, Bluetooth permissions and disabled purchases in the Bluetooth Drag Racing Android preview.','''<section><h1>Bluetooth Drag Racing privacy policy</h1><p>Updated November 8, 2026. This describes the current development preview, package com.tripperdeelabs.bluetoothracing, by TripperDeeLabs.</p><h2>Data stays on your device</h2><p>The game stores your chosen driver name, local identifier, earned credits, owned cars, upgrades, paints, wheel finishes, tuning, settings, race totals, records and recorded ghost runs in app storage. There is no developer account, cloud-save service or developer analytics service. The candidate includes Google Mobile Ads, UMP privacy controls and Google Play Billing, with production advertising and checkout disabled pending setup and verification. The local identifier is used for game identity, not advertising.</p><p>Ghost recordings contain race timing, position and car state, not video, audio or location. Clearing app storage or uninstalling removes local game data. Android backup is disabled in the app manifest; device transfer behavior can vary.</p><h2>Optional Bluetooth</h2><p>The game requests Nearby devices access to connect to paired Android devices. Driver names, car builds, control inputs and race state are exchanged directly with your opponent over Bluetooth. They are not sent to a TripperDeeLabs server. Solo play does not require Bluetooth permission. The app does not request location, microphone, camera or contacts access.</p><h2>Age groups and advertising</h2><p>An optional neutral age-group choice is stored on the device; we do not request a birth date. Players under 18 and those who do not specify an age receive no ads. For adults, advertising requires a fresh Google UMP privacy check. Missing setup, errors or an ineligible age leave ads off. Production ads are disabled in this candidate. Development builds may use Google demonstration ads.</p><p>When enabled and permitted, only non-personalized, maximum-G-rated interstitials may appear after a completed race when leaving the results or starting another solo race. Connected Bluetooth rematches are not interrupted by advertising. Ads are never required to finish a race; offline or unavailable ads do not block continuing. Non-personalized advertising can still process IP addresses, device/app information, ad interactions and diagnostics for delivery and fraud prevention. Advertising ID permission is removed. There is no mediation network in this candidate.</p><p>Use Settings → Privacy &amp; purchases to change the age group, review applicable ad privacy choices, or read this policy. Under-18 and unknown-age players do not initialize the ad SDK or request ads. Adult consent requirements and US-state privacy choices must be configured before activation.</p><h2>Optional purchases</h2><p>Play Billing connection and checkout remain disabled until products, pricing, verification and testing are complete. Proposed one-time products are a metallic paint pack, cosmetic gold wheel finish and the Apex GT car. Performance tire upgrades currently use earned credits only. Earned-credit alternatives remain available and do not charge money. When checkout is enabled, Google Play handles payments; the developer does not receive card details. The app verifies signed purchase records, stores paid ownership separately from earned ownership, acknowledges completed purchases and supports restoration. Pending payments do not unlock items. Refund checks can remove paid ownership while preserving earned items.</p><h2>Your choices and support</h2><p>You can change your driver name and settings in the game and revoke Bluetooth permission in Android settings. Email <a href="mailto:tripperdeelabs@gmail.com">tripperdeelabs@gmail.com</a> with privacy questions or support requests. We receive the information you choose to send and use it to respond; do not include passwords or payment details.</p><p>Website analytics are separate from the app and described in the <a href="/privacy/">website privacy policy</a>.</p><p><a href="/bluetooth-racing/">Game overview</a> · <a href="/bluetooth-racing/support/">Support</a></p></section>''')
 page('/bluetooth-racing/support/','Bluetooth Drag Racing support','Launch, shift, tune, save ghosts and connect a nearby friend in Bluetooth Drag Racing.','''<section><h1>Bluetooth Drag Racing support</h1><h2>Your first run</h2><p>Choose quarter mile or half mile on Home. Tap the mode selector to cycle Rookie, Street, Pro and Ghost. Hold Gas during the countdown to rev; the car stays staged until green. Keep Gas held to launch. Tap Shift as RPM enters the green shift band, or select Automatic in Settings. There is no brake pedal or false-start penalty.</p><h2>Ghosts and records</h2><p>Finish a computer race to save your first ghost for that car and distance. Ghost mode replays your fastest recorded run. A faster completed solo run replaces it. Quarter-mile and half-mile runs, car builds, weather and surface records are stored separately. The cars coast beyond the line before results; that animation does not change the measured finish time.</p><h2>Garage and upgrades</h2><p>Drag the garage car sideways to rotate it. Paint choices save immediately. Open Collection and Car Showroom for cars and cosmetic unlocks. Cars keep separate parts and final-drive settings. Performance Shop shows the six upgrade types. Dyno &amp; Gearing compares simulated acceleration against RPM; its quarter-mile estimate is a game calculation, not real horsepower.</p><h2>Bluetooth is in testing</h2><p>Install the same build on both Android devices, enable Bluetooth and pair them in Android settings. Choose Host on one device and Join on the other. Allow Nearby devices access, choose the host and start when connected. Keep both games in the foreground. Physical two-device acceptance is still pending; report disconnections or synchronization problems with both device models and the app version.</p><h2>Settings and troubleshooting</h2><p>The gear opens settings; the Home icon returns. Choose shifting mode, speed units, control side, audio, frame rate and pedal target size. Solo gameplay works offline. Production ads and cash checkout are not enabled in this candidate. Settings → Privacy &amp; purchases contains the age-group choice, ad privacy options, policy and purchase restoration. Under-18 and unspecified-age players receive no ads. Do not clear storage or uninstall if you want to keep your builds and records.</p><p>Email <a href="mailto:tripperdeelabs@gmail.com?subject=Bluetooth%20Drag%20Racing%20support">tripperdeelabs@gmail.com</a> with the app version, device model and steps to reproduce a problem.</p><p><a href="/bluetooth-racing/">Game overview</a> · <a href="/bluetooth-racing/privacy/">Privacy policy</a></p></section>''')
 home=ROOT/'index.html';soup=BeautifulSoup(home.read_text(),'html.parser');listing=soup.select_one('#in-development .app-directory');assert listing is not None
 for link in listing.select('a[href="/bluetooth-racing/"]'):
  parent=link.find_parent('li')
  if parent:parent.decompose()
 item=BeautifulSoup(f'<li><a class="directory-preview" href="/bluetooth-racing/"><img src="{base}race.png" loading="lazy" alt="Bluetooth Drag Racing side-on race"></a><div class="directory-copy"><h3><a href="/bluetooth-racing/">Bluetooth Drag Racing</a></h3><p class="availability">In development</p><p>Build your garage, chase your ghost and race the quarter or half mile. Nearby Bluetooth racing is in testing.</p><p><a href="/bluetooth-racing/">Explore the game</a> · <a href="/bluetooth-racing/privacy/">Privacy</a></p></div></li>','html.parser').li
 listing.insert(0,item);home.write_text(str(soup))

# Keep regenerated app pages accessible without requiring the portfolio-wide enhancer.
_original_build = build
def build(page):
 def accessible_page(path, *args, **kwargs):
  page(path, *args, **kwargs)
  file=ROOT/path.strip('/')/'index.html'
  doc=BeautifulSoup(file.read_text(),'html.parser')
  main=doc.find('main');main['id']='main-content';main['tabindex']='-1'
  if not doc.select_one('a.skip-link'):
   link=doc.new_tag('a',href='#main-content');link['class']='skip-link';link.string='Skip to content';doc.body.insert(0,link)
  file.write_text(str(doc)+'\n')
 _original_build(accessible_page)
